<script setup lang="ts">
import {computed,onMounted,ref,toRef,watch} from 'vue'
import UiButton from '@/components/ui/UiButton.vue'
import UiDialog from '@/components/ui/UiDialog.vue'
import UiSelectField from '@/components/ui/UiSelectField.vue'
import ObjectScopeTree from './ObjectScopeTree.vue'
import {useConfigFileV2Store} from './file-store-v2'
import {displayPath} from '@/lib/paths'
import {clientLabels} from '@/features/extensions/presentation'
import type {ObjectEntryV2} from './api-v2'
import type {FileImportObjectV2} from './file-api-v2'
const props=withDefaults(defineProps<{source?:'saved'|'draft';importOnly?:boolean;importOpen?:boolean;actionOnly?:boolean;dialogOwner?:boolean;workspace?:boolean}>(),{dialogOwner:false,workspace:true}),emit=defineEmits<{'update:importOpen':[value:boolean];close:[]}>()
const files=useConfigFileV2Store(),accountPlatform=ref('all'),search=ref(''),password=ref(''),encrypt=ref(false),readPassword=ref(''),chooseOpen=toRef(files,'chooseOpen')
const kinds:Record<string,string>={channel:'渠道与模型',template:'模型模版',preferences:'管理器偏好',extensions:'扩展配置',account:'账户信息',skill:'Skill',mcp:'MCP',webdav_candidate:'WebDAV连接'}
const categories:Record<string,string>={channel:'channels',template:'templates',account:'accounts',skill:'skills',mcp:'mcps',preferences:'manager',extensions:'manager',webdav_candidate:'endpoints'}
const exportTree=computed(()=>[(files.destination==='custom'?'自定义导出目录（确认后选择）':'默认导出目录'), '└── <日期>/', '    └── <单次备份包>/', '        ├── '+(files.exportPlan?.filename??'配置文件'), '        └── manifest / 校验信息'].join('\n'))
const key=(kind:string,id:string)=>JSON.stringify([kind,id])
const objects=computed(()=>[...files.entries.map(e=>({id:key(e.kind,e.id),category:categories[e.kind]??e.kind,categoryLabel:kinds[e.kind]??e.kind,label:e.label,detail:e.kind==='mcp'&&e.id==='node_repl'?'由客户端应用维护 · 含本机路径':e.kind==='channel'?'节点、模型精确ID与明确配置；凭据单独选择':e.kind==='account'?'仅账户信息；不携带不受支持的登录状态':'明确选择实际保存对象',disabled:e.kind==='account'&&!files.catalog?.accounts.some(a=>a.account.id===e.id&&a.informationSupported),mark:e.kind==='account'&&!files.catalog?.accounts.some(a=>a.account.id===e.id&&a.informationSupported)?'暂不支持':e.secretAvailable?'可另选凭据':'配置'})),...(files.catalog?.webdavConnections??[]).map(c=>({id:key('webdav_candidate',c.id),category:'endpoints',categoryLabel:'WebDAV连接',label:c.label,detail:c.url+' · '+c.remotePath+' · '+c.username,mark:c.passwordAvailable?'可另选连接密码':'连接配置'}))])
const selectedIds=computed(()=>[...files.entries.filter(e=>files.selected(e)).map(e=>key(e.kind,e.id)),...files.scope.selection.manager.webdavIds.map(id=>key('webdav_candidate',id))])
const platforms:Record<string,string>={chatgpt:'ChatGPT',antigravity:'Google Antigravity',kiro:'Kiro',muse:'Muse'}
const accountFilterIds=computed(()=>objects.value.filter(o=>o.category!=='accounts'||accountPlatform.value==='all'||(files.catalog?.accounts.find(a=>a.account.id===JSON.parse(o.id)[1])?.account.origin?.accountPlatform??'legacy')===accountPlatform.value).map(o=>o.id))
const account=(id:string)=>files.catalog?.accounts.find(a=>a.account.id===id)?.account
function updateIds(ids:string[]){const selected=new Set(ids);for(const e of files.entries)if(files.selected(e)!==selected.has(key(e.kind,e.id)))files.toggleEntry(e,selected.has(key(e.kind,e.id)));const next=JSON.parse(JSON.stringify(files.scope));next.selection.manager.webdavIds=(files.catalog?.webdavConnections??[]).filter(c=>selected.has(key('webdav_candidate',c.id))).map(c=>c.id);next.selection.manager.webdavPasswordIds=next.selection.manager.webdavPasswordIds.filter((id:string)=>next.selection.manager.webdavIds.includes(id));if(JSON.stringify(next)!==JSON.stringify(files.scope))files.setScope(next)}
function entry(id:string){const[kind,value]=JSON.parse(id);return files.entries.find(e=>e.kind===kind&&e.id===value)}
const channel=(id:string)=>files.scope.selection.channels.find(c=>c.portableChannelId===id)
function subset(e:ObjectEntryV2,kind:'all'|'models'|'families'){files.editChannel(e.id,kind,kind==='models'?[...e.modelIds]:kind==='families'?[...e.familyIds]:[])}
function toggleSubset(e:ObjectEntryV2,kind:'models'|'families',id:string,value:boolean){const old=(kind==='models'?channel(e.id)?.modelIds:channel(e.id)?.familyIds)??[];files.editChannel(e.id,kind,value?[...new Set([...old,id])]:old.filter(i=>i!==id))}
function secret(e:ObjectEntryV2,value:boolean){const next=JSON.parse(JSON.stringify(files.scope)),field=e.kind==='skill'?'skillNames':'mcpNames';next.selection.extensionCredentials[field]=next.selection.extensionCredentials[field].filter((id:string)=>id!==e.id);if(value)next.selection.extensionCredentials[field].push(e.id);files.setScope(next)}
function webdavPassword(id:string,value:boolean){const next=JSON.parse(JSON.stringify(files.scope));next.selection.manager.webdavPasswordIds=next.selection.manager.webdavPasswordIds.filter((i:string)=>i!==id);if(value)next.selection.manager.webdavPasswordIds.push(id);files.setScope(next)}
async function prepare(){const pass=encrypt.value?password.value||null:null;password.value='';if(encrypt.value&&!pass){files.error='请填写本次导出保护口令。';return}await files.prepareExport(pass)}
function openImport(){readPassword.value='';chooseOpen.value=true;emit('update:importOpen',true)}
async function chooseFile(){const pass=readPassword.value||null;readPassword.value='';await files.openImport(pass);if(files.importOpen){chooseOpen.value=false;emit('update:importOpen',false)}}
function incomingChannel(id:string){return files.importScope.channels.find(c=>c.portableChannelId===id)}
function mutateImport(action:(s:typeof files.importScope,b:typeof files.bindings)=>void){const scope=JSON.parse(JSON.stringify(files.importScope)),bindings=JSON.parse(JSON.stringify(files.bindings));action(scope,bindings);files.setImport(scope,bindings)}
function toggleImport(o:FileImportObjectV2,value:boolean){mutateImport((s,b)=>{switch(o.kind){case'channel':s.channels=s.channels.filter(c=>c.portableChannelId!==o.id);if(value)s.channels.push({portableChannelId:o.id,modelIds:o.exportedModelIds??null,familyIds:o.exportedFamilyIds??null,includeConnection:o.connectionAvailable&&!o.exportedFamilyIds,includeKey:false,includeAuthorization:false});else{b.channels=b.channels.filter(c=>c.portableChannelId!==o.id);b.adoptNamespaceChannelIds=b.adoptNamespaceChannelIds.filter(id=>id!==o.id)}break;case'template':s.templateRefs=s.templateRefs.filter(r=>r.templateId!==o.id);s.adoptTemplateDefaults=s.adoptTemplateDefaults.filter(r=>r.templateId!==o.id);if(value)s.templateRefs.push(...o.templateReferences);break;case'preferences':s.manager.preferences=value;break;case'extensions':s.manager.extensions=value;break;case'account':if(value&&!o.informationSupported)return;s.manager.accountIds=s.manager.accountIds.filter(id=>id!==o.id);if(value)s.manager.accountIds.push(o.id);break;case'webdav_candidate':s.manager.webdavIds=s.manager.webdavIds.filter(id=>id!==o.id);s.manager.webdavPasswordIds=s.manager.webdavPasswordIds.filter(id=>id!==o.id);if(value)s.manager.webdavIds.push(o.id);break;case'skill':s.skillNames=s.skillNames.filter(id=>id!==o.id);if(value)s.skillNames.push(o.id);else s.extensionCredentials.skillNames=s.extensionCredentials.skillNames.filter(id=>id!==o.id);break;case'mcp':s.mcpSources=s.mcpSources.filter(m=>m.name!==o.id);if(value&&o.definitionDigest)s.mcpSources.push({name:o.id,definitionDigest:o.definitionDigest});else{s.extensionCredentials.mcpNames=s.extensionCredentials.mcpNames.filter(id=>id!==o.id);delete b.mcpClients[o.id]}}})}
function binding(id:string,value:string){mutateImport((_s,b)=>{b.channels=b.channels.filter(c=>c.portableChannelId!==id);if(value==='new')b.channels.push({kind:'new',portableChannelId:id});else if(value)b.channels.push({kind:'existing',portableChannelId:id,localChannelId:value})})}
function bindingValue(id:string){const value=files.bindings.channels.find(c=>c.portableChannelId===id);return value?.kind==='new'?'new':value?.kind==='existing'?value.localChannelId:''}
function importSubset(o:FileImportObjectV2,kind:'all'|'models'|'families'){mutateImport((s,b)=>{const c=s.channels.find(c=>c.portableChannelId===o.id);if(!c)return;c.modelIds=kind==='models'?[...(o.exportedModelIds??o.modelIds)]:o.exportedModelIds??null;c.familyIds=kind==='families'?[...(o.exportedFamilyIds??o.familyIds)]:o.exportedFamilyIds??null;if(kind==='models')c.familyIds=null;if(kind==='families'){c.modelIds=null;c.includeConnection=false;c.includeKey=false;c.includeAuthorization=false}if(c.modelIds!==null||c.familyIds!==null)b.adoptNamespaceChannelIds=b.adoptNamespaceChannelIds.filter(id=>id!==o.id)})}
function importSubId(o:FileImportObjectV2,kind:'models'|'families',id:string,value:boolean){mutateImport(s=>{const c=s.channels.find(c=>c.portableChannelId===o.id);if(!c)return;const field=kind==='models'?'modelIds':'familyIds';c[field]=value?[...new Set([...(c[field]??[]),id])]:(c[field]??[]).filter(v=>v!==id)})}
function importOption(o:FileImportObjectV2,field:'includeConnection'|'includeKey'|'includeAuthorization',value:boolean){mutateImport(s=>{const c=s.channels.find(c=>c.portableChannelId===o.id);if(!c||c.familyIds!==null&&value)return;c[field]=value;if(field==='includeKey'&&value)c.includeAuthorization=false;if(field==='includeAuthorization'&&value)c.includeKey=false})}
const bindingOptions=(o:FileImportObjectV2)=>[{value:'',label:'请选择明确接收目标'},...(o.newIdentityAvailable?[{value:'new',label:'新建独立渠道身份'}]:[]),...o.existingChannelIds.map(id=>({value:id,label:files.catalog?.entries.find(e=>e.kind==='channel'&&e.id===id)?.label??id}))]
watch(()=>props.importOpen,value=>{if(value)openImport()},{immediate:true})
onMounted(async()=>{if(props.source)await files.setSource(props.source);if(props.workspace&&!props.importOnly&&!files.catalog)await files.loadCatalog()})
function errorMessage(value:string|undefined){if(value==='passphrase_required')return '请输入此配置文件的保护口令。';if(value==='file_selection_required')return '请选择本次要导入的配置。';return value&&/^[a-z][a-z0-9_]+$/.test(value)?'本次操作未完成，请重试；当前选择与已有配置保持。':value}
</script>
<template>
 <section class="config-file-v2" aria-label="本机配置文件导入导出">
  <template v-if="workspace&&!importOnly&&!actionOnly"><header class="file-toolbar"><div><h2>导入与导出</h2><p>按下方范围导出配置；导入时在所选文件内选择范围。</p></div><div class="file-actions"><UiButton :disabled="files.busy" @click="openImport">导入配置</UiButton><UiButton variant="primary" :disabled="files.busy||files.loading||!files.catalog||!files.scopeReady||!!files.scopeError" @click="prepare">导出配置</UiButton><details class="file-more"><summary class="btn">更多</summary><div class="file-more-content"><UiButton :disabled="files.busy" @click="files.loadCatalog()">重新读取范围目录</UiButton>  <label class="file-source">导出来源<UiSelectField :model-value="files.source" label="导出来源" :disabled="files.busy" :options="[{value:'saved',label:'已保存配置'},{value:'draft',label:'当前未保存渠道草稿'}]" @update:model-value="files.setSource($event as 'saved'|'draft')" /></label><p v-if="files.source==='draft'">导出当前未保存的渠道草稿与精确模版依赖；运行配置保持，草稿导出不携带凭据。已确认的本地型号和渠道编辑会随本次草稿捕获；未确认的行输入继续保留。</p></div></details></div></header>
<p v-if="files.loading" role="status">正在读取本机配置目录…</p>
  <div class="file-scope-workspace" data-testid="sync-scope-workspace"><section class="file-scope"><div class="file-search"><input v-model="search" class="input" type="search" aria-label="搜索配置对象" placeholder="搜索配置对象" /></div><ObjectScopeTree :objects="objects" :visible-ids="accountFilterIds" :selected-ids="selectedIds" :query="search" label="导出配置对象" name-label="导出范围" :disabled="files.busy||files.loading" @update:selected-ids="updateIds"><template #group-options="{category}"><UiSelectField v-if="category==='accounts'" v-model="accountPlatform" label="账户平台筛选" :disabled="files.busy" :options="[{value:'all',label:'全部平台'},...Object.entries(platforms).map(([value,label])=>({value,label})),{value:'legacy',label:'来源未登记'}]" /></template><template #options="{object}">
   <template v-if="entry(object.id)"><template v-if="entry(object.id)!.kind==='channel'&&files.selected(entry(object.id)!)"><UiSelectField :model-value="channel(entry(object.id)!.id)?.modelIds!==null?'models':channel(entry(object.id)!.id)?.familyIds!==null?'families':'all'" :label="object.label+'模型范围'" :disabled="files.busy" :options="[{value:'all',label:'全渠道模型'},{value:'models',label:'逐模型选择'},{value:'families',label:'按模型族片段'}]" @update:model-value="subset(entry(object.id)!,$event as 'all'|'models'|'families')" /><div v-if="channel(entry(object.id)!.id)?.modelIds!==null"><label v-for="model in entry(object.id)!.models" :key="model.rawModelId"><input type="checkbox" :checked="channel(entry(object.id)!.id)?.modelIds?.includes(model.rawModelId)" :disabled="files.busy" @change="toggleSubset(entry(object.id)!,'models',model.rawModelId,($event.target as HTMLInputElement).checked)" />{{model.label}}<code>{{model.rawModelId}}</code></label></div><div v-if="channel(entry(object.id)!.id)?.familyIds!==null"><label v-for="id in entry(object.id)!.familyIds" :key="id"><input type="checkbox" :checked="channel(entry(object.id)!.id)?.familyIds?.includes(id)" :disabled="files.busy" @change="toggleSubset(entry(object.id)!,'families',id,($event.target as HTMLInputElement).checked)" />{{id}}</label></div><label><input type="checkbox" :checked="channel(entry(object.id)!.id)?.includeConnection" :disabled="files.busy||channel(entry(object.id)!.id)?.familyIds!==null" @change="files.channelOption(entry(object.id)!.id,'includeConnection',($event.target as HTMLInputElement).checked)" />包含渠道连接</label></template>
   <template v-if="entry(object.id)!.kind==='template'"><div v-for="reference in entry(object.id)!.revisions" :key="reference.revisionId"><label><input type="checkbox" :checked="files.scope.selection.templateRefs.some(r=>r.templateId===reference.templateId&&r.revisionId===reference.revisionId)" :disabled="files.busy" @change="files.revision(reference,($event.target as HTMLInputElement).checked)" />{{reference.revisionId}}</label><label><input type="checkbox" :checked="files.scope.selection.adoptTemplateDefaults.some(r=>r.templateId===reference.templateId&&r.revisionId===reference.revisionId)" :disabled="files.busy||!files.scope.selection.templateRefs.some(r=>r.templateId===reference.templateId&&r.revisionId===reference.revisionId)" @change="files.revision(reference,($event.target as HTMLInputElement).checked,true)" />明确采用该保存版本为默认</label></div></template>
   <template v-if="entry(object.id)!.kind==='mcp'"><UiSelectField :model-value="files.scope.mcpClients[entry(object.id)!.id]??''" :label="object.label+'定义来源'" :disabled="files.busy" :options="[{value:'',label:'请选择明确来源'},...(files.catalog?.mcpSources.find(m=>m.name===entry(object.id)!.id)?.sources??[]).map(s=>({value:s.source,label:s.source}))]" @update:model-value="files.mcpSource(entry(object.id)!.id,$event)" /><p>同名 MCP 定义差异：{{files.catalog?.mcpSources.find(m=>m.name===entry(object.id)!.id)?.differingFields.join('、')||'未报告差异'}}。未选来源不会自动采用。</p></template>
   <p v-if="entry(object.id)!.kind==='account'">仅账户信息；本机路径、登录状态与不受支持的会话凭据保持在原设备。</p><dl v-if="entry(object.id)!.kind==='account'&&account(entry(object.id)!.id)"><dt>平台</dt><dd>{{account(entry(object.id)!.id)!.origin?.accountPlatform??account(entry(object.id)!.id)!.provider}}</dd><dt>管理方</dt><dd>{{account(entry(object.id)!.id)!.origin?.owner??'来源未登记'}}</dd><dt>来源账户</dt><dd>{{account(entry(object.id)!.id)!.origin?.sourceAccountId??'未登记'}}</dd><dt>主体 / 组织</dt><dd>{{account(entry(object.id)!.id)!.subject??'未知'}} / {{account(entry(object.id)!.id)!.origin?.tenant??'未知'}}</dd></dl></template>
   <template v-if="JSON.parse(object.id)[0]==='webdav_candidate'"><p>导入后形成未启用的连接候选，不改当前连接。</p><label><input type="checkbox" :checked="files.scope.selection.manager.webdavPasswordIds.includes(JSON.parse(object.id)[1])" :disabled="files.busy||files.source==='draft'||!files.scope.selection.manager.webdavIds.includes(JSON.parse(object.id)[1])||!files.catalog?.webdavConnections.find(c=>c.id===JSON.parse(object.id)[1])?.passwordAvailable" @change="webdavPassword(JSON.parse(object.id)[1],($event.target as HTMLInputElement).checked)" />包含此连接密码</label></template>
  </template></ObjectScopeTree></section>
  <aside aria-label="其他凭据与内容保护" data-testid="sync-scope-credentials"><h3>其他凭据</h3><template v-for="e in files.entries.filter(e=>files.selected(e))" :key="e.kind+e.id"><template v-if="e.kind==='channel'"><label><input type="checkbox" :checked="channel(e.id)?.includeKey" :disabled="files.busy||files.source==='draft'||!e.keyAvailable||channel(e.id)?.familyIds!==null" @change="files.channelOption(e.id,'includeKey',($event.target as HTMLInputElement).checked)" />{{e.label}} · API Key</label><label><input type="checkbox" :checked="channel(e.id)?.includeAuthorization" :disabled="files.busy||files.source==='draft'||!e.authorizationAvailable||channel(e.id)?.familyIds!==null" @change="files.channelOption(e.id,'includeAuthorization',($event.target as HTMLInputElement).checked)" />{{e.label}} · 受支持授权</label></template><label v-if="e.kind==='skill'||e.kind==='mcp'"><input type="checkbox" :checked="e.kind==='skill'?files.scope.selection.extensionCredentials.skillNames.includes(e.id):files.scope.selection.extensionCredentials.mcpNames.includes(e.id)" :disabled="files.busy||files.source==='draft'||!e.secretAvailable" @change="secret(e,($event.target as HTMLInputElement).checked)" />{{e.label}} · 扩展凭据</label></template><label><input v-model="encrypt" type="checkbox" :disabled="files.busy" />保护导出内容</label><label v-if="encrypt">保护口令<input v-model="password" class="input" type="password" aria-label="导出保护口令" autocomplete="new-password" :disabled="files.busy" /></label><p>保护口令与 WebDAV 连接密码分别选择；口令不进入范围偏好。</p></aside></div>
  <details class="file-advanced"><summary>高级选项</summary><p>全局设置包含模版引用、默认渠道和渠道组顺序。勾选后会将这些设置包含在配置包中，接收时可明确选择是否采用；未勾选时不包含。</p><label><input type="checkbox" :checked="files.scope.selection.includeGlobalTemplateRefs" :disabled="files.busy" @change="files.setScope({...files.scope,selection:{...files.scope.selection,includeGlobalTemplateRefs:($event.target as HTMLInputElement).checked}})" />包含这些全局设置</label></details>
  <details v-if="files.recoverable.length"><summary>原文件操作 · {{files.recoverable.length}}</summary><div v-for="op in files.recoverable" :key="op.operationId"><span>{{op.kind==='export'?'导出':'导入'}} · {{op.operationId}} · {{op.completed?'已有回执':op.attempted?'原操作待核对':'尚未执行'}}</span><UiButton :disabled="files.busy" @click="files.reopen(op)">重开原操作</UiButton></div></details></template>
  <p v-if="workspace&&files.scopeError" role="alert" class="model-error">{{files.scopeError}}<UiButton :disabled="files.loading||files.busy" @click="files.loadCatalog()">重新读取范围</UiButton></p><p v-if="workspace&&files.error" role="alert" class="model-error">{{errorMessage(files.error)}}</p><p v-if="workspace&&files.status" role="status">{{files.status}}</p>
  <template v-if="dialogOwner"><UiDialog :open="files.scopeOpen" title="配置文件范围" wide @close="files.scopeOpen=false"><ConfigFileTransferV2 v-if="files.scopeOpen" /></UiDialog>
  <UiDialog :open="chooseOpen" title="选择配置文件" :busy="files.busy" @close="chooseOpen=false;emit('update:importOpen',false)"><p>尚未选择文件。选择本机配置文件后，核对内容和接收目标。</p><label>受保护文件的读取口令<input v-model="readPassword" class="input" type="password" aria-label="导入读取口令" autocomplete="off" :disabled="files.busy" /></label><p v-if="files.error" role="alert" class="model-error">{{errorMessage(files.error)}}</p><template #actions="{close}"><UiButton :disabled="files.busy" @click="close">取消</UiButton><UiButton variant="primary" :disabled="files.busy" @click="chooseFile">选择本机文件</UiButton></template></UiDialog>
  <UiDialog :open="files.exportOpen" title="确认导出" :busy="files.busy" wide @close="files.closeExport"><template v-if="files.exportPlan"><section v-if="!files.exportAttempted" class="export-destination" aria-label="导出目录"><h3>导出目录</h3><label><input v-model="files.destination" type="radio" value="default" :disabled="files.busy" name="file-export-destination" />默认导出目录</label><label><input v-model="files.destination" type="radio" value="custom" :disabled="files.busy" name="file-export-destination" />自定义目录（确认后选择目录…）</label></section><p v-else role="status">原操作的首次输出目录保持固定，重试不会重新选择位置。</p><section class="export-tree"><h3>生成位置</h3><pre>{{exportTree}}</pre><p>以上为目录结构示意，实际位置在生成后显示。同日多次导出各自建包；复制整个备份包即可带到另一台设备。</p></section><p>{{files.exportPlan.filename}} · {{files.exportPlan.encrypted?'已保护':'未保护'}} · {{files.exportPlan.length}} 字节</p><p>渠道 {{files.exportPlan.summary.channelIds.length}} · 模版 {{files.exportPlan.summary.templateIds.length}} · 账户 {{files.exportPlan.summary.accountCount}} · Skill {{files.exportPlan.summary.skillCount}} · MCP {{files.exportPlan.summary.mcpCount}} · WebDAV {{files.exportPlan.summary.webdavCount}}</p><p>渠道 Key {{files.exportPlan.summary.channelKeyCount}} · 授权 {{files.exportPlan.summary.channelAuthorizationCount}} · 连接密码 {{files.exportPlan.summary.webdavPasswordCount}} · 扩展凭据 {{files.exportPlan.summary.extensionSecretCount}}</p><p v-if="!files.exportPlan.encrypted&&(files.exportPlan.summary.channelKeyCount+files.exportPlan.summary.channelAuthorizationCount+files.exportPlan.summary.webdavPasswordCount+files.exportPlan.summary.extensionSecretCount)>0" class="model-error">未启用内容保护；所选凭据将保存在导出文件中。</p><p v-if="files.exportStale" role="alert">选择已变化，请关闭并重新准备。</p><p v-if="files.error" role="alert" class="model-error">{{errorMessage(files.error)}}</p></template><template #actions="{close}"><UiButton :disabled="files.busy" @click="close">取消</UiButton><UiButton variant="primary" :disabled="!files.canSaveExport" @click="files.saveExport">{{files.exportAttempted?'继续原配置包导出':files.destination==='custom'?'选择目录…':'生成配置包'}}</UiButton></template></UiDialog>
  <UiDialog :open="files.importOpen" title="导入配置预览" :busy="files.busy" wide panel-class="config-file-import-v2" @close="files.closeImport"><p>只采用本次明确选择的对象与目标，未选内容保持；文件中的连接密码与内容保护口令分开处理。确认时会结束未修改的模型编辑会话，有未保存输入时将停止。</p><p v-if="files.importAttempted">原操作已尝试执行，范围保持冻结；重试将核对同一操作，不重新选择文件。</p><article v-for="o in files.importPreview?.objects??[]" :key="o.kind+o.id" class="file-incoming-object"><label><input type="checkbox" :aria-label="'采用 '+o.label" :checked="files.importSelected(o)" :disabled="files.busy||files.importAttempted||o.kind==='account'&&!o.informationSupported" @change="toggleImport(o,($event.target as HTMLInputElement).checked)" /><strong>{{o.label}}</strong><span>{{kinds[o.kind]??o.kind}}</span></label><template v-if="files.importSelected(o)">
   <template v-if="o.kind==='channel'"><UiSelectField :model-value="bindingValue(o.id)" :label="o.label+'接收目标'" :options="bindingOptions(o)" :disabled="files.busy||files.importAttempted" @update:model-value="binding(o.id,$event)" /><UiSelectField :model-value="incomingChannel(o.id)?.modelIds!==null?'models':incomingChannel(o.id)?.familyIds!==null?'families':'all'" :label="o.label+'采用模型范围'" :options="[{value:'all',label:'文件内完整渠道范围',disabled:!!o.exportedModelIds||!!o.exportedFamilyIds},{value:'models',label:'逐模型选择',disabled:!!o.exportedFamilyIds},{value:'families',label:'按族片段选择'}]" :disabled="files.busy||files.importAttempted" @update:model-value="importSubset(o,$event as 'all'|'models'|'families')" /><label v-for="id in incomingChannel(o.id)?.modelIds!==null?o.modelIds:incomingChannel(o.id)?.familyIds!==null?o.familyIds:[]" :key="id"><input type="checkbox" :checked="incomingChannel(o.id)?.modelIds?.includes(id)||incomingChannel(o.id)?.familyIds?.includes(id)" :disabled="files.busy||files.importAttempted" @change="importSubId(o,incomingChannel(o.id)?.modelIds!==null?'models':'families',id,($event.target as HTMLInputElement).checked)" />{{id}}</label><label><input type="checkbox" :checked="incomingChannel(o.id)?.includeConnection" :disabled="files.busy||files.importAttempted||!o.connectionAvailable||incomingChannel(o.id)?.familyIds!==null" @change="importOption(o,'includeConnection',($event.target as HTMLInputElement).checked)" />采用连接</label><label v-if="o.hasKey"><input type="checkbox" :checked="incomingChannel(o.id)?.includeKey" :disabled="files.busy||files.importAttempted||incomingChannel(o.id)?.familyIds!==null" @change="importOption(o,'includeKey',($event.target as HTMLInputElement).checked)" />采用渠道 Key</label><label v-if="o.hasAuthorization"><input type="checkbox" :checked="incomingChannel(o.id)?.includeAuthorization" :disabled="files.busy||files.importAttempted||incomingChannel(o.id)?.familyIds!==null" @change="importOption(o,'includeAuthorization',($event.target as HTMLInputElement).checked)" />采用受支持授权</label><label v-if="o.namespaceRequiresAdoption"><input type="checkbox" :checked="files.bindings.adoptNamespaceChannelIds.includes(o.id)" :disabled="files.busy||files.importAttempted||incomingChannel(o.id)?.modelIds!==null||incomingChannel(o.id)?.familyIds!==null" @change="mutateImport((_s,b)=>{b.adoptNamespaceChannelIds=b.adoptNamespaceChannelIds.filter(id=>id!==o.id);if(($event.target as HTMLInputElement).checked)b.adoptNamespaceChannelIds.push(o.id)})" />明确采用文件中的渠道命名空间（仅完整渠道）</label></template>
   <template v-if="o.kind==='template'"><div v-for="r in o.templateReferences" :key="r.revisionId"><label><input type="checkbox" :checked="files.importScope.templateRefs.some(v=>v.templateId===r.templateId&&v.revisionId===r.revisionId)" :disabled="files.busy||files.importAttempted" @change="mutateImport(s=>{s.templateRefs=s.templateRefs.filter(v=>v.templateId!==r.templateId||v.revisionId!==r.revisionId);if(($event.target as HTMLInputElement).checked)s.templateRefs.push(r);else s.adoptTemplateDefaults=s.adoptTemplateDefaults.filter(v=>v.templateId!==r.templateId||v.revisionId!==r.revisionId)})" />{{r.revisionId}}</label><label><input type="checkbox" :checked="files.importScope.adoptTemplateDefaults.some(v=>v.templateId===r.templateId&&v.revisionId===r.revisionId)" :disabled="files.busy||files.importAttempted||!files.importScope.templateRefs.some(v=>v.templateId===r.templateId&&v.revisionId===r.revisionId)" @change="mutateImport(s=>{s.adoptTemplateDefaults=s.adoptTemplateDefaults.filter(v=>v.templateId!==r.templateId);if(($event.target as HTMLInputElement).checked)s.adoptTemplateDefaults.push(r)})" />明确采用为默认保存版本</label></div></template>
   <dl v-if="o.kind==='account'&&o.accountInfo"><dt>平台</dt><dd>{{o.accountInfo.origin?.accountPlatform??o.accountInfo.provider}}</dd><dt>管理方</dt><dd>{{o.accountInfo.origin?.owner??'来源未登记'}}</dd><dt>来源账户</dt><dd>{{o.accountInfo.origin?.sourceAccountId??'未登记'}}</dd><dt>主体 / 组织</dt><dd>{{o.accountInfo.subject??'未知'}} / {{o.accountInfo.origin?.tenant??'未知'}}</dd></dl><UiSelectField v-if="o.kind==='mcp'" :model-value="files.bindings.mcpClients[o.id]??''" :label="o.label+'接收客户端'" :options="[{value:'',label:'请选择接收客户端'},...Object.entries(clientLabels).map(([value,label])=>({value,label}))]" :disabled="files.busy||files.importAttempted" @update:model-value="mutateImport((_s,b)=>{if($event)b.mcpClients[o.id]=$event;else delete b.mcpClients[o.id]})" />
   <label v-if="o.kind==='webdav_candidate'&&o.hasCredentials"><input type="checkbox" :checked="files.importScope.manager.webdavPasswordIds.includes(o.id)" :disabled="files.busy||files.importAttempted" @change="mutateImport(s=>{s.manager.webdavPasswordIds=s.manager.webdavPasswordIds.filter(id=>id!==o.id);if(($event.target as HTMLInputElement).checked)s.manager.webdavPasswordIds.push(o.id)})" />采用此未启用连接候选的密码</label><label v-if="(o.kind==='skill'||o.kind==='mcp')&&o.hasCredentials"><input type="checkbox" :checked="o.kind==='skill'?files.importScope.extensionCredentials.skillNames.includes(o.id):files.importScope.extensionCredentials.mcpNames.includes(o.id)" :disabled="files.busy||files.importAttempted" @change="mutateImport(s=>{const k=o.kind==='skill'?'skillNames':'mcpNames';s.extensionCredentials[k]=s.extensionCredentials[k].filter(id=>id!==o.id);if(($event.target as HTMLInputElement).checked)s.extensionCredentials[k].push(o.id)})" />采用本项扩展凭据</label></template></article>
  <details><summary>高级选项</summary><p>采用包内全局模版引用、默认渠道和渠道组顺序，会更新本机对应设置。未勾选时保留本机这些设置。</p><label><input type="checkbox" :checked="files.importScope.includeGlobalTemplateRefs" :disabled="files.busy||files.importAttempted" @change="mutateImport(s=>{s.includeGlobalTemplateRefs=($event.target as HTMLInputElement).checked})" />采用包内这些全局设置</label></details><label><input v-model="files.backup" type="checkbox" :disabled="files.busy||files.importAttempted" />更新前备份</label><p v-if="files.comparing" role="status">正在核对本次明确范围；新输入会保留并继续比较。</p><p v-if="files.importStale" role="status">本次范围已调整，正在更新预览。</p><p v-if="files.importPreview?.reasonCode" role="alert" class="model-error">{{errorMessage(files.importPreview.reasonCode)}}</p><p v-if="files.error" role="alert" class="model-error">{{errorMessage(files.error)}}</p><details v-if="files.importPreview"><summary>本次实际变更范围</summary><p>渠道：{{files.importPreview.differences.changedChannelIds.join('、')||'无已确认变化'}}</p><p>精确模版：{{files.importPreview.differences.changedTemplateRefs.map(r=>r.templateId+'/'+r.revisionId).join('、')||'无已确认变化'}}</p></details><template #actions="{close}"><UiButton :disabled="files.busy" @click="close">取消</UiButton><UiButton v-if="files.importStale&&files.error&&!files.comparing" :disabled="files.busy||files.importAttempted" @click="files.compareImport">重试更新预览</UiButton><UiButton variant="primary" :disabled="!files.canConfirmImport" @click="files.confirmImport">{{files.importAttempted?'核对并继续原采用':'确认采用所选配置'}}</UiButton></template></UiDialog>
  <UiDialog :open="files.resultOpen" title="文件操作结果" @close="files.resultOpen=false"><template v-if="files.receipt?.operationId===files.resultOperationId"><p>原操作 {{files.receipt.operationId}}</p><p>文件内容已核对 · {{files.receipt.length}} 字节</p><p>文件摘要 {{files.receipt.fileDigest}}</p><template v-if="files.output?.operationId===files.resultOperationId"><h3>实际生成位置</h3><p class="local-path">{{displayPath(files.output.path)}}</p><p>备份包目录：<code>{{displayPath(files.output.directory)}}</code></p><div class="file-actions"><UiButton :disabled="files.busy" @click="files.openOutputDirectory()">打开备份包目录</UiButton><UiButton :disabled="files.busy" @click="files.readOutput()">重新核对输出位置</UiButton></div></template><p>关闭结果不重复导出或采用。</p></template><template v-else-if="files.originalRecord"><p>原操作 {{files.originalRecord.operationId}}</p><p>{{files.originalRecord.completed?'后端原操作已有完成回执':'原操作仍待核对'}}</p><p>此处只显示原操作记录，未重新导出或采用。</p></template><p v-if="files.error" role="alert" class="model-error">{{errorMessage(files.error)}}</p></UiDialog>
 </template></section>
</template>
<style scoped>
.config-file-v2{display:grid;align-content:start;gap:var(--space-4);min-width:0;width:100%}.file-toolbar,.file-actions{display:flex;align-items:center;justify-content:space-between;gap:var(--space-2);flex-wrap:wrap}.file-toolbar h2{font-size:var(--text-subtitle);margin:0}.file-toolbar p{color:var(--muted)}label{display:flex;gap:var(--space-2);align-items:center;min-width:0;margin-block:var(--space-2)}.config-file-v2 input:not([type=checkbox]){min-width:0;box-sizing:border-box}.file-scope-workspace{display:grid;grid-template-columns:minmax(0,1fr) minmax(200px,280px);gap:var(--space-5)}aside{padding-inline-start:var(--space-4);border-inline-start:1px solid var(--border)}aside label{margin-block:var(--space-3)}.file-incoming-object{display:grid;gap:var(--space-3);padding-block:var(--space-4);border-bottom:1px solid var(--border)}.export-tree pre{white-space:pre-wrap;overflow-wrap:anywhere;padding:var(--space-3);border:1px solid var(--border);border-radius:var(--radius)}.model-error{color:var(--red)}code,p{overflow-wrap:anywhere}.file-scope{display:grid;align-content:start;gap:var(--space-3);min-width:0}.file-search{display:flex;min-width:0}.file-search>.input{height:var(--control-md);flex:1;width:100%;min-width:140px}.file-more{position:relative}.file-more>summary{list-style:none;cursor:pointer}.file-more>summary::-webkit-details-marker{display:none}.file-more-content{position:absolute;right:0;top:calc(100% + 4px);z-index:6;display:grid;gap:var(--space-3);width:min(360px,70vw);padding:var(--space-3);border:1px solid var(--border);border-radius:var(--radius-sm);background:var(--panel);box-shadow:var(--shadow)}.file-more-content p{margin:0}.file-advanced{margin-top:var(--space-2)}@media(max-width:760px){.file-scope-workspace{grid-template-columns:minmax(0,1fr)}aside{padding-inline-start:0;border-inline-start:0;border-top:1px solid var(--border)}}
</style>
